function validarCorreo(t){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(t)}function validarPassword(t){return/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&._\-#])[A-Za-z\d@$!%*?&._\-#]{8,}$/.test(t)}function validarLongitud(t,e){return String(t).trim().length<=e}function calcularEdad(t){const e=new Date,n=new Date(t);let r=e.getFullYear()-n.getFullYear();const a=e.getMonth()-n.getMonth();return(a<0||0===a&&e.getDate()<n.getDate())&&r--,r}function esMayorDeEdad(t){return calcularEdad(t)>=18}function soloLetras(t){return/^[a-zA-ZáéíóúÁÉÍÓÚñÑ\s]+$/.test(t)}function validarTelefono(t){return/^\d{10}$/.test(String(t).trim())}function ocultarTexto(t,e=4){const n=String(t);return n.length<=e?n:"*".repeat(n.length-e)+n.slice(-e)}